import{_ as a,o,c as i,a2 as r}from"./chunks/framework.DCVnL8g5.js";const p=JSON.parse('{"title":"Buenas prácticas","description":"","frontmatter":{},"headers":[],"relativePath":"ia/vllm/07-buenas-practicas.md","filePath":"ia/vllm/07-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),t={name:"ia/vllm/07-buenas-practicas.md"};function n(l,e,s,c,d,u){return o(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h1><p>Los capítulos 1–6 ya cubren casos de uso, API OpenAI, carga, batching, arranque y métricas. Aquí no se vuelve a explicar cómo levantar <code>vllm serve</code> ni la tabla de <code>/metrics</code>. El trabajo es <strong>decidir</strong>: qué modelo entra, cuánta VRAM dejas, cómo no abrir el puerto a Internet, y cómo no romper producción en un upgrade.</p><p>Documentación oficial: <a href="https://docs.vllm.ai/en/latest/cli/serve/" target="_blank" rel="noreferrer">CLI serve</a>, <a href="https://docs.vllm.ai/en/latest/usage/security/" target="_blank" rel="noreferrer">Security</a>, <a href="https://docs.vllm.ai/en/latest/design/metrics/" target="_blank" rel="noreferrer">métricas</a>, <a href="https://docs.vllm.ai/en/latest/deployment/docker.html" target="_blank" rel="noreferrer">Docker</a>.</p><h2 id="seleccion-de-modelo" tabindex="-1">Selección de modelo <a class="header-anchor" href="#seleccion-de-modelo" aria-label="Permalink to &quot;Selección de modelo&quot;">​</a></h2><p>Antes del flag, el card del Hub:</p><ul><li><strong>Compatibilidad:</strong> arquitectura que tu versión de vLLM carga. Un checkpoint que exige <code>trust_remote_code</code> no es “el mismo” que un modelo nativo.</li><li><strong>Contexto:</strong> el máximo del card no es un objetivo. Si el producto usa 2k tokens, no reserves 128k.</li><li><strong>VRAM:</strong> pesos + KV. Si no cabe, cuantiza (<code>--quantization</code> alineado con el repo), modelo más pequeño, o tensor parallelism (capítulo 5). No subas contexto “por si acaso”.</li><li><strong>Cuantización:</strong> usa el método del <code>quantization_config</code> del repo. Mezclar GGUF con flags AWQ es perder la tarde.</li></ul><p>Fija <strong>id + revision</strong> (capítulo 3). <code>latest</code> en la imagen Docker y <code>main</code> en el Hub son dos fuentes de no-reproducibilidad.</p><h2 id="memoria" tabindex="-1">Memoria <a class="header-anchor" href="#memoria" aria-label="Permalink to &quot;Memoria&quot;">​</a></h2><p>Receta operativa cuando hay OOM o KV llena (los flags están en la CLI; no inventes otros):</p><ol><li>Baja <code>--max-model-len</code> al máximo que el producto necesita.</li><li>Baja <code>--gpu-memory-utilization</code> (default <strong>0.92</strong>, <em>por instancia</em>) si compartes GPU o ves OOM al pico.</li><li>Sube <code>-tp</code> solo si tienes esas GPUs y el modelo (o la KV) lo justifica.</li><li>Cambia de checkpoint (más pequeño o cuantizado).</li></ol><p><code>--gpu-memory-utilization</code> no es “usa el 92 % de la máquina”: es la fracción que <strong>esta</strong> instancia puede reclamar. Dos procesos a 0.92 en la misma GPU se pisan.</p><p>Mide <code>vllm:kv_cache_usage_perc</code> (capítulo 6) antes de tocar más flags. Si la KV está al máximo y hay cola, te faltan bloques, no “un restart”.</p><h2 id="rendimiento" tabindex="-1">Rendimiento <a class="header-anchor" href="#rendimiento" aria-label="Permalink to &quot;Rendimiento&quot;">​</a></h2><p>Throughput (tokens/s del <em>servicio</em>) y latencia (TTFT / ITL de <em>una</em> petición) tiran en sentidos opuestos: más batch suele mejorar GPU y empeorar la cola percibida.</p><p>Continuous batching ya está en serving; no hay un interruptor que “activar PagedAttention”. El trabajo es:</p><ul><li>definir un SLO (p95 TTFT o tokens/s a N concurrentes);</li><li>reproducir la mezcla real de longitudes;</li><li>cambiar <strong>un</strong> parámetro (<code>max-num-seqs</code>, contexto, utilización);</li><li>volver a medir.</li></ul><p>Una petición suelta no valida un despliegue. El capítulo 4 es el banco de pruebas; este capítulo es la norma: no optimices a ciegas.</p><h2 id="seguridad" tabindex="-1">Seguridad <a class="header-anchor" href="#seguridad" aria-label="Permalink to &quot;Seguridad&quot;">​</a></h2><p><code>--api-key</code> (o <code>VLLM_API_KEY</code>) autentica rutas bajo <code>/v1</code>, <code>/v2</code> e <code>/inference</code>. <strong>No</strong> cubre el resto del proceso HTTP: la documentación de seguridad lista utilidades (<code>/health</code>, <code>/metrics</code>, <code>/tokenize</code>, <code>/version</code>, …) y otras rutas de inferencia que siguen accesibles sin Bearer.</p><p>Consecuencias prácticas:</p><ul><li>No publiques el puerto 8000 a Internet, ni con <code>--api-key</code>.</li><li>Pon un <strong>proxy</strong> (TLS, allowlist de paths, rate limit, auth de verdad). Deja <code>/health</code> para probes; no dejes <code>/metrics</code> ni tokenize abiertos al mundo.</li><li>Red privada / NetworkPolicy entre el backend y vLLM.</li><li><code>--trust-remote-code</code> solo con origen auditado (capítulo 3).</li><li>Logs: <code>--enable-log-requests</code> puede grabar prompts (PII). En producción, asume que el prompt es dato sensible.</li></ul><p>vLLM es un motor de inferencia, no un API gateway.</p><h2 id="operacion" tabindex="-1">Operación <a class="header-anchor" href="#operacion" aria-label="Permalink to &quot;Operación&quot;">​</a></h2><ul><li><strong>Vivo:</strong> probe a <code>GET /health</code> (liveness) y, cuando el modelo ya cargó, <code>GET /v1/models</code> (readiness de API). Distingue “el proceso escucha” de “el peso está en VRAM”.</li><li><strong>Métricas:</strong> scrape de <code>/metrics</code> en la red interna (capítulo 6). Alertas sobre <code>rate()</code> de counters y histogramas, no sobre un curl de chat.</li><li><strong>Logs:</strong> stdout del contenedor + correlación con deploys (imagen digest + id de modelo + revision).</li><li><strong>Restart / rolling:</strong> vLLM carga el modelo al arrancar; un restart es un hueco. En réplicas: levanta la nueva con el <strong>mismo</strong> snapshot, espera <code>/v1/models</code>, luego corta tráfico. No hagas rolling de un <code>-tp</code> 2 a 1 “a ver qué pasa” en el mismo Deployment sin probar.</li><li><strong>Cache de pesos</strong> en volumen para no saturar el Hub en cada reschedule.</li></ul><h2 id="versionado" tabindex="-1">Versionado <a class="header-anchor" href="#versionado" aria-label="Permalink to &quot;Versionado&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Qué fijar</th><th>Por qué</th></tr></thead><tbody><tr><td>Imagen <code>vllm/vllm-openai:&lt;tag&gt;</code> o versión del paquete</td><td>El motor cambia flags y kernels.</td></tr><tr><td>Id del modelo + <code>revision</code></td><td><code>main</code> se mueve.</td></tr><tr><td>Flags de contexto / utilización</td><td>El mismo binario con 32k no es el mismo servicio.</td></tr></tbody></table><p>Un upgrade de vLLM o de pesos es un <strong>experimento</strong>: staging con el mismo mix de carga, comparar TTFT y calidad (un set de prompts), luego producción. No mezcles cambio de modelo y cambio de versión del motor en el mismo deploy si puedes evitarlo.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Confiar en <code>--api-key</code> como único control.</li><li>Dejar 0.92 de utilización junto a un entrenamiento o un segundo <code>vllm</code>.</li><li>Subir contexto al máximo del card porque “cabe en el README”.</li><li>Comparar latencia de batch 1 con un blog que mide 32 usuarios.</li><li>Actualizar <code>latest</code> el viernes sin pin.</li></ul><h2 id="buenas-practicas-resumen" tabindex="-1">Buenas prácticas (resumen) <a class="header-anchor" href="#buenas-practicas-resumen" aria-label="Permalink to &quot;Buenas prácticas (resumen)&quot;">​</a></h2><ul><li>Pin de motor, modelo y revision.</li><li>SLO escrito; un cambio por vez; métricas del capítulo 6.</li><li>Proxy delante; GPU en red privada.</li><li>OOM: contexto → utilización → tamaño/cuantización/TP, en ese orden salvo evidencia.</li><li>Staging con tráfico sintético que parezca el real.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Con el servidor del capítulo 5, identifica en la doc de seguridad tres rutas que <strong>no</strong> exige <code>--api-key</code>.</li><li>Escribe el pin (imagen + modelo + revision + <code>max-model-len</code>) que usarías en staging.</li><li>Diseña un probe: qué URL es liveness y cuál es “ya puedo mandar chat”.</li></ol>',33)])])}const g=a(t,[["render",n]]);export{p as __pageData,g as default};
